const eventContentKeys=['act','title','copy','quote','left','right','rightOption','result','upHint','blockHint','lockedLeft','lockedUp','a','b'];
const eventConditionKeys=['minYear','maxYear','ranks','requiresCompanion','requiresMaster','requiresEstate','requiresArtifact','requiresConfiguredArtifact','requiresTalent','requiresDemonVictory','rootGrades','worldCycles','requiresStatus','requiresPath','causalKey'];
function cleanEventContent(content={}){if(!content||typeof content!=='object'||Array.isArray(content))throw new Error('剧情内容配置无效');const cleaned={};eventContentKeys.forEach(key=>{if(!(key in content))return;const value=content[key];if(['a','b'].includes(key)){if(!value||typeof value!=='object'||Array.isArray(value))throw new Error(`剧情结果配置无效：${key}`);cleaned[key]={...value};return}if(['lockedLeft','lockedUp'].includes(key)){if(typeof value!=='boolean')throw new Error(`剧情锁定配置无效：${key}`);cleaned[key]=value;return}if(typeof value!=='string')throw new Error(`剧情文本配置无效：${key}`);cleaned[key]=value});return cleaned}
function cleanEventCondition(condition={}){if(!condition||typeof condition!=='object'||Array.isArray(condition))throw new Error('剧情条件配置无效');const cleaned={};eventConditionKeys.forEach(key=>{if(!(key in condition))return;const value=condition[key];if(['minYear','maxYear'].includes(key)){if(!Number.isFinite(Number(value)))throw new Error(`剧情条件数值无效：${key}`);cleaned[key]=Number(value);return}if(['ranks','rootGrades','worldCycles'].includes(key)){if(!Array.isArray(value)||value.some(item=>typeof item!=='string'))throw new Error(`剧情条件列表无效：${key}`);cleaned[key]=[...value];return}if(['requiresArtifact','requiresMaster','requiresEstate','requiresTalent','requiresDemonVictory'].includes(key)){if(typeof value!=='boolean')throw new Error(`剧情条件开关无效：${key}`);cleaned[key]=value;return}if(typeof value!=='string')throw new Error(`剧情条件文本无效：${key}`);if(key==='requiresConfiguredArtifact'&&!artifactOverrides[value])throw new Error(`剧情条件引用了未配置法宝：${value}`);cleaned[key]=value});if('minYear' in cleaned&&'maxYear' in cleaned&&cleaned.minYear>cleaned.maxYear)throw new Error('剧情条件年份范围无效：最小年份不能晚于最大年份');return cleaned}
Object.entries(eventConditionOverrides).forEach(([eventType,condition])=>{eventConditionOverrides[eventType]=cleanEventCondition(condition)});
Object.entries(eventContentOverrides).forEach(([eventType,content])=>{eventContentOverrides[eventType]=cleanEventContent(content)});
function activeArtifactResonances(){return Object.entries(artifactResonanceOverrides).filter(([,resonance])=>Array.isArray(resonance?.requires)&&resonance.requires.length&&resonance.requires.every(id=>state.artifacts?.includes(id)))}
function artifactResonanceBonus(key){return activeArtifactResonances().reduce((total,[,resonance])=>{const value=Number(resonance[key]||0);return Number.isFinite(value)?total+value:total},0)}
function artifactResonanceScale(key){return activeArtifactResonances().reduce((total,[,resonance])=>{const value=Number(resonance[key]||1);return Number.isFinite(value)&&value>0?total*value:total},1)}
function artifactBonus(key){return(state.artifacts||[]).reduce((total,id)=>{const value=Number(artifactOverrides[id]?.[key]||0);return Number.isFinite(value)?total+value:total},0)+artifactResonanceBonus(key)}
function artifactScale(key){return(state.artifacts||[]).reduce((total,id)=>{const value=Number(artifactOverrides[id]?.[key]||1);return Number.isFinite(value)&&value>0?total*value:total},1)*artifactResonanceScale(key)}
function artifactEffectSummary(id){const artifact=artifactOverrides[id];if(!artifact)return'';const effects=[];if(artifact.combatBonus)effects.push(`战力 +${artifact.combatBonus}`);if(artifact.meditationScale&&artifact.meditationScale!==1)effects.push(`打坐效率 +${Math.round((artifact.meditationScale-1)*100)}%`);if(artifact.recovery)effects.push(`气血恢复 ${artifact.recovery>0?'+':''}${artifact.recovery}`);if(artifact.breakthroughBonus)effects.push(`突破 +${Math.round(artifact.breakthroughBonus*100)}%`);if(artifact.examBonus)effects.push(`评定 +${artifact.examBonus}`);if(artifact.active)effects.push(`主动：${artifact.active.label||'可发动'}`);return effects.join(' · ')}
function cleanArtifactRewards(value){const ids=Array.isArray(value)?value:[value];if(!ids.length||ids.some(id=>typeof id!=='string'||!artifactOverrides[id]))throw new Error('法宝奖励必须引用已配置的法宝');return ids}
function cleanArtifactResonance(value){if(!value||typeof value!=='object'||!value.name||!Array.isArray(value.requires)||!value.requires.length||value.requires.some(id=>typeof id!=='string'||!artifactOverrides[id]))throw new Error('法宝共鸣配置无效');for(const key of ['combatBonus','meditationScale','recovery','breakthroughBonus','examBonus']){if(key in value&&!Number.isFinite(Number(value[key])))throw new Error(`法宝共鸣属性无效：${key}`)}if('meditationScale' in value&&Number(value.meditationScale)<=0)throw new Error('法宝共鸣打坐倍率必须为正');return{...value,requires:[...value.requires]}}
function announceArtifactResonances(previous){const oldIds=new Set(previous),newlyActive=activeArtifactResonances().filter(([id])=>!oldIds.has(id));newlyActive.forEach(([,resonance])=>{addLog(`<strong>法宝共鸣 · ${resonance.name||'无名共鸣'}已激活。</strong>${resonance.description||'多件法宝的力量正在彼此呼应。'}`);$('statusMessage').textContent=`法宝共鸣「${resonance.name||'无名共鸣'}」已激活。`})}
function announceArtifactResonanceLoss(previous,removed={}){const currentIds=new Set(activeArtifactResonances().map(([id])=>id));previous.filter(id=>!currentIds.has(id)).forEach(id=>{const resonance=artifactResonanceOverrides[id]||removed[id];addLog(`<strong>法宝共鸣 · ${resonance?.name||'无名共鸣'}已消退。</strong>所需法宝不再齐备，额外加成暂时失效。`);$('statusMessage').textContent=`法宝共鸣「${resonance?.name||'无名共鸣'}」已消退。`})}
function grantConfiguredArtifacts(ids){(Array.isArray(ids)?ids:[ids]).filter(Boolean).forEach(id=>{if(artifactOverrides[id])QingyunStoryAPI.grantArtifact(id,false)})}
function relationshipImpact(eventType,side){const direct=cleanRelationshipChanges(relationshipRules[eventType]?.[side]),total={...direct};Object.entries(direct).forEach(([source,change])=>Object.entries(relationshipInfluenceRules[source]||{}).forEach(([target,ratio])=>{const ripple=Math.round(change*ratio);if(ripple)total[target]=(total[target]||0)+ripple}));return Object.fromEntries(Object.entries(total).filter(([,value])=>value))}
function applyRelationship(eventType,side){if(!state.relations)return;const changes=relationshipImpact(eventType,side);Object.entries(changes).forEach(([key,value])=>state.relations[key]=Math.max(-100,Math.min(100,state.relations[key]+value)))}
function relationLabel(value){if(value>=80)return'生死相托';if(value>=50)return'知己';if(value>=30)return'亲近';if(value>=10)return'熟悉';if(value<=-60)return'仇视';if(value<=-30)return'疏远';if(value<=-10)return'冷淡';return'初识'}
