function personClue(key){const profile=npcProfiles[key],value=state.relations[key],met=state.npcStories[key],year=state.yearsElapsed||0,bonded=state.companionKey===key;if(!met)return{state:'未相遇',tone:'locked',text:`修行第 ${profile.firstYear} 年将出现人物事件。`};if(!state.affectionResolved)return value>=15?{state:'可结缘',tone:'ready',text:`好感达到 15。第15年若为三人最高，将触发${profile.name}的因缘回应。`}:{state:'因缘尚浅',tone:'pending',text:`距离结缘门槛还差 ${15-value} 好感；第15年将进行因缘判定。`};if(!bonded)return{state:'支线留痕',tone:'quiet',text:`第15年未与${profile.name}同行，此线索保留为此世旧识。`};if(!state.bondAwakeningResolved)return{state:'同行中',tone:'ready',text:'第35年羁绊显化，可从两件永久信物中选择其一。'};if(!state.laterStory?.companion)return{state:'羁绊已成',tone:'ready',text:`信物「${bondBoonInfo().name}」生效；第45年将迎来故人后续。`};return{state:'因果已证',tone:'resolved',text:'同行与故人后续均已完成，将影响最终结局。'}}
function renderCausalClues(){const panel=$('causalCluesPanel'),list=$('causalCluesList'),count=$('causalClueCount');if(!panel||!list)return;if(!state.unlocked){panel.classList.add('clues-locked');count.textContent='第一幕后解锁';return}panel.classList.remove('clues-locked');const people=Object.keys(npcProfiles).map(key=>{const profile=npcProfiles[key],clue=personClue(key);return`<div class="causal-clue ${clue.tone}"><i>${profile.icon}</i><div><strong>${profile.name}<em>${clue.state}</em></strong><span>${clue.text}</span></div></div>`});const threads=causalState(),causes=[['spring','泉','后山灵泉',24],['tax','简','三年份例',36],['apprentice','药','失踪药童',48]].map(([key,icon,title,echoYear])=>{const chosen=threads[key],resolved=threads[`${key}Resolved`],boon=state.causalBoons?.[key];let clueState='尚未埋下',text='相关卡牌尚未出现，继续修行与探索。',tone='locked';if(chosen&&!resolved){clueState='因果酝酿';text=`你的选择已被记下，将在修行第 ${echoYear} 年回应。`;tone='pending'}if(resolved){clueState='已经回应';text=`${causalBoonCatalog[boon]?.name||'因果已结'}：${causalBoonCatalog[boon]?.description||'这段因果已经完成。'}`;tone='resolved'}return`<div class="causal-clue ${tone}"><i>${icon}</i><div><strong>${title}<em>${clueState}</em></strong><span>${text}</span></div></div>`});const active=Object.keys(npcProfiles).filter(key=>state.npcStories[key]).length+['spring','tax','apprentice'].filter(key=>threads[key]).length,resolved=(state.affectionResolved?1:0)+['spring','tax','apprentice'].filter(key=>threads[`${key}Resolved`]).length;count.textContent=`${active} 条已发现 · ${resolved} 条已回应`;list.innerHTML=`<div class="clue-group-title">人物因缘</div>${people.join('')}<div class="clue-group-title">多年伏笔</div>${causes.join('')}`}
function artifactRackItems(){const items=[];if(state.inventory?.relationshipBook)items.push({id:'relationshipBook',name:'人缘册',image:'assets/artifacts/renyuan-book-cover.jpg',hint:'人物因缘与因果线索'});if(state.secretArtifact)items.push({id:'secretArtifact',name:secretArtifactInfo().name,image:null,icon:secretArtifactInfo().icon,hint:'秘境法宝 · 点击查看'});if(state.bondBoon)items.push({id:'bondBoon',name:bondBoonInfo().name,image:null,icon:bondBoonInfo().icon,hint:'羁绊信物 · 点击查看'});(state.artifacts||[]).forEach(id=>{const artifact=artifactOverrides[id];if(artifact){const resonance=artifactResonanceText(id);items.push({id:`artifact:${id}`,name:artifact.name||id,image:artifact.image||null,icon:artifact.icon||'宝',hint:[artifact.hint||'配置法宝',artifactEffectSummary(id),resonance].filter(Boolean).join(' · '),resonant:Boolean(resonance),cooldown:state.artifactCooldowns?.[id]||0})}});return items}
