function renderRelations(){const panel=$('relationsPanel'),summary=$('relationBookSummary'),relationText=`柳 ${state.relations.steward>=0?'+':''}${state.relations.steward} · 苏 ${state.relations.peers>=0?'+':''}${state.relations.peers} · 璃 ${state.relations.spirit>=0?'+':''}${state.relations.spirit}`;if(summary)summary.textContent=relationText;renderArtifactRack();if(!state.unlocked){panel.classList.add('relations-locked');renderCausalClues();return}panel.classList.remove('relations-locked');[['steward','Steward'],['peers','Peers'],['spirit','Spirit']].forEach(([key,suffix])=>{const value=state.relations[key],previous=previousRelationValues?.[key],bar=$(`relation${suffix}`),text=$(`relation${suffix}Text`),next=$(`relation${suffix}Next`),relation=bar.closest('.relation'),bonded=state.companionKey===key,note=relation.querySelector('p');if(Number.isFinite(previous)&&previous!==value)flashRelation(key,value-previous);bar.style.width=`${Math.min(100,Math.max(0,(value+100)/2))}%`;text.textContent=`${bonded?'同行 · ':''}${relationLabel(value)} · ${value>=0?'+':''}${value}`;next.textContent=nextRelationMilestone(value);note.textContent=bonded&&state.bondBoon?`信物：${bondBoonInfo().name} · 永久生效`:relationEffectText(key,value);relation.classList.toggle('negative',value<0);relation.classList.toggle('bonded',bonded)});previousRelationValues={...state.relations};renderCausalClues()}
