function techniqueAffinityInfo(id=selectedTechniqueId()){const technique=techniqueInfo(id),affinity=technique.affinity;if(!affinity)return{matched:true,bonus:0,label:'诸法均衡'};const attributes=state?.root?.attributes||[],targets=Array.isArray(affinity)?affinity:[affinity],matched=targets.some(item=>attributes.includes(item));if(matched)return{matched:true,bonus:.06,label:`灵根相合 · ${Array.isArray(affinity)?'五行':affinity} +6%`};const baseElements=['金','木','水','火','土'];if(Array.isArray(affinity)&&affinity.length===5&&!attributes.some(item=>baseElements.includes(item)))return{matched:true,bonus:0,label:'灵根相容 · 变异属性不受五行相克'};const supported=targets.find(item=>attributes.includes(wuxingRelations.support[item]));if(supported)return{matched:true,bonus:.03,label:`灵根相生 · ${wuxingRelations.support[supported]}生${supported} +3%`};const controlled=targets.find(item=>attributes.includes(wuxingRelations.control[item]));if(controlled)return{matched:false,bonus:-.03,label:`灵根相克 · ${wuxingRelations.control[controlled]}克${controlled} -3%`};return{matched:false,bonus:-.04,label:`灵根相冲 · ${Array.isArray(affinity)?'五行':affinity} -4%`}}
function techniqueMasteryValue(id=selectedTechniqueId()){return state.techniqueMasteries?.[id]??(id==='qingyun'?(state.techniqueMastery||0):0)}
function techniqueStage(mastery=techniqueMasteryValue()){if(mastery>=80)return{name:'大成',multiplier:1.5,meditationBonus:50,breakthroughBonus:.2,examBonus:20,floor:80,next:null};if(mastery>=30)return{name:'小成',multiplier:1.35,meditationBonus:35,breakthroughBonus:.15,examBonus:15,floor:30,next:80};return{name:'入门',multiplier:1.2,meditationBonus:20,breakthroughBonus:.1,examBonus:10,floor:0,next:30}}
function meditationRewards(){const stage=techniqueStage(),technique=techniqueInfo(),affinity=techniqueAffinityInfo(),boon=bondBoonInfo(),talent=innateTalentInfo(),artifact=secretArtifactInfo(),causal=causalBonusInfo(),world=worldCycleInfo(),status=statusModifier(),path=pathBonusInfo(),gain=Math.max(1,Math.round(18*state.root.efficiency*(state.techniqueEquipped?stage.multiplier*technique.meditationScale*(1+affinity.bonus):1)*(boon.meditationScale||1)*(talent.meditationScale||1)*(artifact.meditationScale||1)*(causal.meditationScale||1)*(world.meditationScale||1)*(status.meditationScale||1)*artifactScale('meditationScale'))),recovery=Math.max(1,6+(state.relations.spirit>=30?2:state.relations.spirit<=-30?-2:0)+(state.techniqueEquipped?technique.recovery:0)+(boon.recovery||0)+(talent.recovery||0)+(artifact.recovery||0)+(causal.recovery||0)+(world.recovery||0)+(status.recovery||0)+(path.recovery||0)+artifactBonus('recovery'));return{gain,recovery,stage,technique,affinity,boon,talent,artifact,causal,world,status,path}}
function practiceTechnique(){if(!state.techniqueEquipped)return null;const id=selectedTechniqueId(),before=techniqueStage().name;state.techniqueMasteries=state.techniqueMasteries||{qingyun:state.techniqueMastery||0};state.techniqueMasteries[id]=Math.min(80,techniqueMasteryValue(id)+10);if(id==='qingyun')state.techniqueMastery=state.techniqueMasteries[id];const after=techniqueStage();return before!==after.name?after:null}
