function updateBreakthroughUI(){if(!state)return;const level=Math.min(state.realmLevel||0,realms.length-1),event=currentEvent(),forced=state.scene!=='prologue'&&Boolean(event?.lockedUp);$('realm').textContent=realms[level];const button=$('breakthroughButton'),ready=state.scene!=='prologue'&&!forced&&state.qi>=100&&state.life>=choiceLifeCost()&&level<realms.length-1;button.disabled=!ready;button.classList.toggle('ready',ready);button.textContent=ready?`尝试突破 · ${Math.round(breakthroughChance()*100)}`:forced?'当前事件需先抉择':state.scene==='prologue'?'入门后解锁':level>=realms.length-1?'已达最高境界':state.life<choiceLifeCost()?'寿元不足半年':`灵力 ${Math.min(state.qi,100)} / 100`;updateMeterWarnings()}
