function attemptBreakthrough(){if(state.qi<100||state.scene==='prologue'||state.life<choiceLifeCost()||currentEvent()?.lockedUp){if(currentEvent()?.lockedUp)$('statusMessage').textContent=currentEvent().upHint||'当前事件必须先作出选择。';return}captureTurnSnapshot();const boosted=state.breakthroughBoost,chance=breakthroughChance(),success=Math.random()<chance,before={qi:state.qi,hp:state.hp,heart:state.heart,life:state.life};state.breakthroughBoost=false;state.yearsElapsed=(state.yearsElapsed||0)+choiceLifeCost();spendLife(choiceLifeCost());tickStatuses();tickArtifactCooldowns();let resultMessage='';if(success){state.qi-=100;state.realmLevel=Math.min(state.realmLevel+1,realms.length-1);state.fame+=5;state.hp=Math.min(100,state.hp+10);const qiLoss=before.qi-state.qi,hpGain=state.hp-before.hp;resultMessage=`突破成功 · ${realms[state.realmLevel]} · 灵力 -${qiLoss} · 气血 +${hpGain} · 声望 +5 · 寿元 -0.5 年`;addLog(`<strong>突破成功！</strong>${boosted?'破境丹药力护住经脉，':''}你踏入${realms[state.realmLevel]}：灵力 -${qiLoss} · 气血 +${hpGain} · 声望 +5 · 突破耗时半年。`);tone(392,.8,'sine',.05);tone(587,1.1,'sine',.04,.18)}else{state.qi=Math.max(0,state.qi-45);state.hp=Math.max(1,state.hp-12);state.heart=Math.max(0,state.heart-5);const qiLoss=before.qi-state.qi,hpLoss=before.hp-state.hp,heartLoss=before.heart-state.heart;resultMessage=`突破失败 · 灵力 -${qiLoss} · 气血 -${hpLoss} · 道心 -${heartLoss} · 寿元 -0.5 年`;addLog(`<strong>突破失败。</strong>${boosted?'破境丹药力已散。':''}灵气反噬：灵力 -${qiLoss} · 气血 -${hpLoss} · 道心 -${heartLoss} · 突破耗时半年。`);if(!boosted)applyStatus('meridianWound',6);tone(130,.4,'sawtooth',.025)}state.round++;render();$('statusMessage').textContent=resultMessage;if(state.life<=0)setTimeout(end,250)}
