function resolveSectStory(event,side){const estate=sectEstateState();if(event.special==='sectPolicy'){estate.policyResolved=true;if(event.role==='master')changeSectEstate(side==='left'?{disciples:25,treasury:-10}:{formation:25,treasury:-8});else changeSectEstate(side==='left'?{disciples:18,treasury:-5}:{formation:18,treasury:-5});addLog(`<strong>宗门方略已定。</strong>${side==='left'?'门人规模扩大':'护山阵势增强'}。当前基业：弟子 ${estate.disciples} · 阵势 ${estate.formation} · 库藏 ${estate.treasury}。`);return}if(event.special==='sectCrisis'){estate.crisisResolved=true;if(side==='left'){changeSectEstate({disciples:-10,treasury:8});addLog('<strong>三峰暂封。</strong>宗门保住核心基业，却有一批弟子黯然离山。');return}const score=estate.disciples+estate.formation+estate.treasury;estate.crisisVictory=score>=85;if(estate.crisisVictory){changeSectEstate({disciples:10,formation:12,treasury:8});state.fame+=20;state.contribution+=15;addLog(`<strong>三峰灵脉重开！</strong>宗门基业 ${score}，达到 85：声望 +20 · 贡献 +15。`);unlockAchievement('sectProsperity');tone(196,.45,'triangle',.035);tone(392,.8,'sine',.035,.16);tone(587,1.1,'sine',.03,.34)}else{changeSectEstate({disciples:-12,formation:-10,treasury:-8});state.hp=Math.max(1,state.hp-15);addLog(`<strong>开脉功败垂成。</strong>宗门基业 ${score}，未达 85：弟子、阵势与库藏受损，气血 -15。`)}}}
function resolveTribulation(side,score){state.tribulationResolved=true;if(side==='left'){state.tribulationSafe=true;addLog('<strong>避雷阵成。</strong>四十块灵石化为齑粉，你借阵法稳稳熬过雷劫。');return}if(score>=110){state.tribulationVictory=true;state.realmLevel=Math.min(state.realmLevel+1,realms.length-1);state.qi+=35;state.fame+=30;state.hp=Math.min(100,state.hp+10);addLog(`<strong>问心雷劫已破！</strong>评定 ${score}。境界提升一层 · 灵力 +35 · 声望 +30。`);tone(98,.45,'sawtooth',.04);tone(392,.8,'triangle',.05,.2);tone(784,1.2,'sine',.04,.45)}else{state.hp=Math.max(1,state.hp-25);state.heart=Math.max(0,state.heart-15);addLog(`<strong>强渡雷劫失败。</strong>评定 ${score}，未达 110。雷火灼身：气血 -25 · 道心 -15。`)}}
function resolveLateStory(event,side,power){state.laterStory[event.storyFlag]=true;if(event.storyFlag==='inner'){if(side==='left'){addLog('<strong>外门执教。</strong>你留在熟悉的山峰，将经验传给后来弟子。');return}const score=Math.round(state.contribution+state.fame*.25+state.heart*.2+(state.companion==='柳管事'?12:0));if(score>=55){state.innerDisciple=true;state.rank='内门弟子';state.fame+=20;state.contribution+=20;addLog(`<strong>三重剑阵已破！</strong>遴选评定 ${score}，你正式成为青云宗内门弟子：声望 +20 · 贡献 +20。`);unlockTechnique('sword')}else{state.hp=Math.max(1,state.hp-15);state.heart=Math.max(0,state.heart-8);addLog(`<strong>剑阵止步。</strong>遴选评定 ${score}，未达 55：气血 -15 · 道心 -8。`)}return}if(event.storyFlag==='tournament'){if(side==='left'){addLog('<strong>知进退。</strong>你保住大比名次，也看清了剑首的真正实力。');return}if(power>=90){state.tournamentVictory=true;state.fame+=35;state.stone+=25;state.contribution+=20;addLog(`<strong>青云大比夺魁！</strong>战力 ${power}。声望 +35 · 灵石 +25 · 贡献 +20。`)}else{state.hp=Math.max(1,state.hp-20);state.heart=Math.max(0,state.heart-8);addLog(`<strong>惜败剑首。</strong>战力 ${power}，未达 90：气血 -20 · 道心 -8。`)}return}if(event.storyFlag==='cave'){if(side==='left'){addLog('<strong>洞府易主。</strong>你换得大笔灵石，却将筑基机缘让给了旁人。');return}const success=(state.realmLevel>=2||state.qi>=150)&&state.heart>=65;if(success){state.foundationSuccess=true;state.realmLevel=Math.max(3,state.realmLevel);state.qi+=30;state.hp=Math.min(100,state.hp+15);addLog('<strong>道基已成！</strong>你在地脉洞府中踏入筑基初期：灵力 +30 · 气血 +15。');unlockTechnique('foundation')}else{state.hp=Math.max(1,state.hp-25);state.qi=Math.max(0,state.qi-40);addLog('<strong>筑基功败垂成。</strong>根基或道心不足：气血 -25 · 灵力 -40。')}return}if(event.storyFlag==='invasion'){if(side==='left'){addLog('<strong>百人归山。</strong>你护送低阶弟子撤入密道，保住了青云宗下一代。');return}if(power>=130){state.invasionVictory=true;state.fame+=45;state.contribution+=30;state.heart+=10;addLog(`<strong>阵眼不破，青云不倒！</strong>战力 ${power}。声望 +45 · 贡献 +30 · 道心 +10。`)}else{state.hp=Math.max(1,state.hp-30);state.heart=Math.max(0,state.heart-15);addLog(`<strong>阵眼失守。</strong>战力 ${power}，未达 130：气血 -30 · 道心 -15。`)}return}if(event.storyFlag==='companion'){state.companionLegacy=true;if(event.person==='spirit'&&side==='left'){state.companion=null;state.companionKey=null;addLog('<strong>灵契已解。</strong>白璃踏月归族，却在离开前留下半枚月华印。')}else if(event.person)addLog(`<strong>故人不散。</strong>你与${npcProfiles[event.person].name}共同走过了这场迟来的考验。`);else addLog('<strong>旧信入匣。</strong>那些未成同行的因缘，也终于有了安放之处。');return}if(event.storyFlag==='succession'){if(side==='left'){state.rank='太上长老';addLog('<strong>退居云峰。</strong>你辞去权位，成为青云宗最清闲也最受敬重的太上长老。');return}const score=Math.round(state.fame*.45+state.contribution*.55+state.heart*.2+(state.innerDisciple?20:0)+(state.invasionVictory?20:0));if(score>=150){state.sectMaster=true;state.rank='青云掌教';state.fame+=35;state.contribution+=25;addLog(`<strong>七峰归心！</strong>掌教评定 ${score}。你接过青云法印，成为新任掌教。`)}else{state.heart=Math.max(0,state.heart-12);state.fame=Math.max(0,state.fame-15);addLog(`<strong>七峰质询未过。</strong>评定 ${score}，未达 150：道心 -12 · 声望 -15。`)}return}if(event.storyFlag==='demonRealm'){if(side==='left'){addLog('<strong>天渊再封。</strong>你以三十块灵石加固封印，为人间换来百年喘息。');return}if(power>=200){state.demonRealmVictory=true;state.realmLevel=Math.min(realms.length-1,Math.max(state.realmLevel+1,6));state.fame+=50;state.heart+=12;addLog(`<strong>魔源已斩！</strong>远征战力 ${power}。境界提升 · 声望 +50 · 道心 +12。`);unlockTechnique('demon')}else{state.hp=Math.max(1,state.hp-35);state.heart=Math.max(0,state.heart-18);addLog(`<strong>魂灯熄灭。</strong>战力 ${power}，未达 200：气血 -35 · 道心 -18。`)}return}if(event.storyFlag==='ascension'){if(side==='left'){state.rank=state.sectMaster?'青云掌教':'青云守山人';addLog('<strong>转身人间。</strong>天门在身后闭合，你选择把余生留给青云宗。');return}const score=Math.round(state.realmLevel*35+state.heart*.35+state.fame*.2+state.contribution*.15+(state.demonRealmVictory?35:0)+(state.companion?15:0));if(score>=220){state.ascended=true;state.realmLevel=realms.length-1;addLog(`<strong>九霄天门已开！</strong>飞升评定 ${score}。你斩断凡尘桎梏，羽化登仙。`)}else{state.hp=Math.max(1,state.hp-30);state.qi=Math.max(0,state.qi-60);state.heart=Math.max(0,state.heart-15);addLog(`<strong>天门拒渡。</strong>评定 ${score}，未达 220：气血 -30 · 灵力 -60 · 道心 -15。`)}}}
function choose(side){const e=currentEvent();if(side==='left'&&e.lockedLeft){showBlocked(e.blockHint);return}if(state.scene!=='prologue')captureTurnSnapshot();const trialPower=e.special==='trial'?combatPower():0,tribulationPower=e.special==='tribulation'?tribulationScore():0,latePower=e.special?.startsWith('late')?combatPower():0;if(state.scene!=='prologue'){state.yearsElapsed=(state.yearsElapsed||0)+.5;tickStatuses()}applyChoice(e,side,state.scene==='prologue'?0:choiceLifeCost());if(state.scene==='prologue'){addLog(`<span class="result-line">${e.result}</span>`);state.prologueStep++;if(state.prologueStep>=prologueEvents.length){state.scene='main';state.unlocked=true;state.rank='杂役弟子';assignQuest();state.round=1;state.yearsElapsed=0;state.eventIndex=pickEvent();addLog('<strong>第一幕完成。</strong>功法、背包、兵刃与宗门任务已解锁。往后每次行动推进半年。')}render();if(state.unlocked)showSystem();bindDrag();return}if(e.special==='relationshipBook')resolveRelationshipBookDiscovery(side);if(e.special==='promotion')resolvePromotion(side);if(e.special==='trial')resolveTrial(side,trialPower);if(e.special==='tribulation')resolveTribulation(side,tribulationPower);if(e.special?.startsWith('sword'))resolveSwordStory(e,side);if(e.special?.startsWith('npc'))resolveNpcStory(e,side);if(e.special==='affection')resolveAffection(e,side);if(e.special?.startsWith('late'))resolveLateStory(e,side,latePower);state.round++;if(state.life<=0||state.ascended){render();setTimeout(end,250);return}state.eventIndex=pickEvent();render();bindDrag();}
function endingById(id){return endingCatalog.find(item=>item.id===id)||endingCatalog[endingCatalog.length-1]}
function endingProfile(){if(state.ascended){if(state.sectMaster&&state.demonRealmVictory&&state.sectEstate?.crisisVictory)return endingById('qingyunAncestor');if(state.companionKey==='spirit')return endingById('moonAscension');if(state.companionKey==='peers')return endingById('swordAscension');if(state.companionKey==='steward')return endingById('mortalAscension');if(!state.companionKey&&state.bondBoon==='solitude')return endingById('loneAscension');return endingById('ascension')}if(state.sectMaster&&state.demonRealmVictory)return endingById('sectLegend');if(state.demonRealmVictory)return endingById('demonReturn');if(state.invasionVictory)return endingById('mountainGuardian');if(state.foundationSuccess&&state.secretArtifact)return endingById('secretSage');if(state.companionKey==='peers'&&state.tribulationVictory)return endingById('swordCompanion');if(state.companionKey==='spirit'&&state.tribulationVictory)return endingById('moonCompanion');if(state.companionKey==='steward'&&state.rank!=='杂役弟子')return endingById('stewardLegacy');if(state.weaponUpgrade&&state.trialVictory)return endingById('swordHero');if(state.foundationSuccess)return endingById('foundationPath');if(state.hp<=20)return endingById('hardRoad');if(state.fame>=100)return endingById('famousLife');return endingById('firstPath')}
function endingTitle(){return endingProfile().title}
function recordEnding(){const profile=endingProfile();meta.endings=Array.isArray(meta.endings)?meta.endings:[];if(!meta.endings.includes(profile.id))meta.endings.push(profile.id);if(meta.endings.length>=5)unlockAchievement('endingCollector');if(!state.endingRecorded){state.endingRecorded=true;meta.runs++;meta.bestRealm=Math.max(meta.bestRealm,state.realmLevel||0);meta.bestFame=Math.max(meta.bestFame,state.fame);if(state.trialVictory)meta.trialWins++}if(!meta.selectedBoon)meta.selectedBoon='spirit';saveMeta();saveGame()}
function selectLegacyBoon(id){if(!legacyBoons[id])return;meta.selectedBoon=id;saveMeta();renderLegacyPanel()}
function renderEndingCodex(){let codex=$('endingCodex');if(!codex){codex=document.createElement('div');codex.id='endingCodex';codex.className='ending-codex';document.querySelector('.legacy-title').before(codex)}const discovered=new Set(meta.endings||[]),current=endingProfile().id;codex.innerHTML=`<div class="ending-codex-head"><strong>因果结局图鉴</strong><span>${discovered.size} / ${endingCatalog.length}</span></div><div class="ending-codex-grid">${endingCatalog.map(item=>`<div class="ending-codex-item ${discovered.has(item.id)?'unlocked':'locked'} ${item.id===current?'current':''}"><b>${discovered.has(item.id)?item.title:'未解锁'}</b><span>${discovered.has(item.id)?item.epilogue:item.hint}</span></div>`).join('')}</div>`}
function renderLegacyPanel(){const bestRealm=realms[Math.min(meta.bestRealm,realms.length-1)];$('legacySummary').innerHTML=`<span>轮回 <b>${meta.runs}</b> 世</span><span>最高境界 <b>${bestRealm}</b></span><span>最高声望 <b>${meta.bestFame}</b></span><span>斩妖 <b>${meta.trialWins}</b> 次</span><span>结局 <b>${(meta.endings||[]).length}</b> 种</span>`;renderEndingCodex();document.querySelectorAll('#legacyChoices button').forEach(button=>{const selected=button.dataset.boon===meta.selectedBoon;button.classList.toggle('selected',selected);button.onclick=()=>selectLegacyBoon(button.dataset.boon)});$('again').textContent=`携「${legacyBoons[meta.selectedBoon].name}」再入太虚`}
function end(){const profile=endingProfile();recordEnding();const r=realms[Math.min(state.realmLevel,realms.length-1)],years=formatYears(state.yearsElapsed||0),bondText=state.companion==='柳管事'?'你始终记得柳管事当年递来的铁牌与旧账。':state.companion?`「${state.companion}」陪你走过了这段不会被山海轻易斩断的因缘。`:'这一程无人同行，却也让你更清楚自己选择的道。',bondLabel=state.companion==='柳管事'?'引路':state.companion?'同行':'声望';$('endingKicker').textContent=state.ascended?'九霄天门已开':'此世寿元已尽';$('ending').textContent=profile.title;$('endingText').textContent=`历经 ${years} 年修行，你以「${state.rank}」身份抵达「${r}」。${bondText}${profile.epilogue}`;$('finalStats').innerHTML=`<span>道龄<b>${years}年</b></span><span>境界<b>${r}</b></span><span>战力<b>${combatPower()}</b></span><span>${bondLabel}<b>${state.companion||state.fame}</b></span>`;renderLegacyPanel();$('modal').classList.remove('hidden');$('again')?.focus({preventScroll:true})}
 $('leftChoice').onclick=()=>choose('left');$('rightChoice').onclick=()=>choose('right');$('restart').onclick=()=>{if(window.confirm('确定要重开此世吗？当前自动存档将被覆盖。'))reset()};$('exportSave').onclick=exportSave;$('importSaveButton').onclick=()=>$('importSaveInput').click();$('importSaveInput').onchange=event=>{importSaveFile(event.target.files?.[0]);event.target.value=''};$('again').onclick=()=>{$('modal').classList.add('hidden');reset()};$('artifactRack').onclick=event=>{const slot=event.target.closest('[data-artifact]');if(slot)inspectArtifact(slot.dataset.artifact)};$('closeArtifactInspector').onclick=closeArtifactInspector;$('artifactInspector').onclick=event=>{if(event.target===$('artifactInspector'))closeArtifactInspector()};$('removeArtifactButton').onclick=removeInspectedArtifact;$('closeRelationBook').onclick=closeRelationshipBook;$('relationModal').onclick=event=>{if(event.target===$('relationModal'))closeRelationshipBook()};const currentEventBase=currentEvent;currentEvent=function(){return applyEventContentOverride(currentEventBase())};loadMeta();protectInvalidSave();loadGame();enhanceRecoveryButton();notifySaveRecovery();notifyImportResult();
 $('useArtifactButton').onclick=()=>{const id=inspectedArtifactId?.startsWith('artifact:')?inspectedArtifactId.slice(9):null;if(id&&QingyunStoryAPI.useArtifact(id))showArtifactActivation(artifactOverrides[id].name,artifactOverrides[id].active?.label)};
 let dragStartX=0,dragging=false;
bindDrag();
const chooseEventBase=choose;
const chooseEvent=side=>{const event=currentEvent();chooseEventBase(side);if(event.special==='bondAwakening')resolveBondAwakening(event,side);if(event.special==='talentAwakening')resolveTalentAwakening(event,side);if(event.special==='pathAwakening')resolvePathAwakening(event,side);if(event.requiresPath)resolvePathTrial(event);if(event.special?.startsWith('secret'))resolveSecretRealm(event,side);if(event.special?.startsWith('sect'))resolveSectStory(event,side);if(event.special?.startsWith('cause'))resolveCausalThread(event,side);if(['bondAwakening','talentAwakening','pathAwakening'].includes(event.special)||event.requiresPath||event.special?.startsWith('secret')||event.special?.startsWith('sect')||event.special?.startsWith('cause')){render();bindDrag()}};
choose=function(side){if(side!=='up'){playChoiceSound();chooseEvent(side);return}const e=currentEvent();if(state.scene==='prologue'){showBlocked('你还未入宗门，暂时没有资格修炼打坐。');return}if(state.life<choiceLifeCost()){showBlocked('寿元不足半年，已经无法进行下一轮修行。');return}if(e.lockedUp){showBlocked(e.upHint);return}captureTurnSnapshot();const{gain,recovery,stage,technique,affinity}=meditationRewards(),beforeQi=state.qi,beforeHp=state.hp;showMeditationAnimation(gain,recovery);state.qi+=gain;state.hp=Math.min(100,state.hp+recovery);const actualQiGain=state.qi-beforeQi,actualHpGain=state.hp-beforeHp;state.yearsElapsed=(state.yearsElapsed||0)+.5;spendLife(.5);tickStatuses();const advanced=practiceTechnique();advanceQuest({qi:actualQiGain,hp:actualHpGain});addLog(`你选择<strong>上滑修炼打坐</strong>：+${actualQiGain} 灵力 · +${actualHpGain} 气血 · -0.5 寿元（半年闭关）${state.techniqueEquipped?` · 《${technique.name}》熟练度 +10（${stage.name}） · ${affinity.label}`:''}。`);if(advanced)addLog(`<strong>《${technique.name}》突破至${advanced.name}！</strong>聚气加成提升为 +${advanced.meditationBonus}%，突破加成提升为 +${Math.round((advanced.breakthroughBonus+technique.breakthroughBonus)*100)}%。`);state.round++;if(state.life<=0||state.ascended){render();setTimeout(end,250);return}state.eventIndex=pickEvent();render();bindDrag()};
function showActionResult(event,side,preview){const toast=document.createElement('div');toast.className='action-result-toast';toast.setAttribute('role','status');toast.setAttribute('aria-live','polite');toast.innerHTML=`<span>半年行动结算</span><strong>${side==='left'?event.left:event.right}</strong><em>${preview||'因果已落定'}</em>`;document.body.appendChild(toast);setTimeout(()=>toast.remove(),2200)}
let choiceInProgress=false,choiceCommitPending=false,pendingChoiceTimer=null;
const performChoice=choose;
choose=function(side){if(choiceInProgress||choiceCommitPending)return;const event=currentEvent(),preview=side==='up'?'打坐收益将在本轮结算':choicePreview(event,side);if((side==='up'&&!event.lockedUp)||(side!=='up'&&!(side==='left'&&event.lockedLeft)))tickArtifactCooldowns();choiceInProgress=true;const scene=document.querySelector('.scene');scene?.setAttribute('aria-busy','true');['leftChoice','rightChoice','restart'].forEach(id=>{const button=$(id);if(button)button.disabled=true});performChoice(side);if(state.scene==='main'){if(side==='up')showMeditationResult(state?.lastSnapshot);else showActionResult(event,side,preview)}if(!document.querySelector('.modal:not(.hidden),.artifact-inspector:not(.hidden)'))document.querySelector('.decision-card')?.focus({preventScroll:true});setTimeout(()=>{choiceInProgress=false;scene?.setAttribute('aria-busy','false');['leftChoice','rightChoice','restart'].forEach(id=>{const button=$(id);if(button)button.disabled=false})},260)};
var audioContext=null;
function getAudio(){if(!audioContext)audioContext=new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();return audioContext}
function tone(frequency,duration,type='sine',volume=.035,delay=0){const audio=getAudio(),osc=audio.createOscillator(),gain=audio.createGain();osc.type=type;osc.frequency.setValueAtTime(frequency,audio.currentTime+delay);gain.gain.setValueAtTime(.0001,audio.currentTime+delay);gain.gain.exponentialRampToValueAtTime(volume,audio.currentTime+delay+.02);gain.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+delay+duration);osc.connect(gain).connect(audio.destination);osc.start(audio.currentTime+delay);osc.stop(audio.currentTime+delay+duration+.03)}
function playChoiceSound(){tone(180,.08,'triangle',.025);tone(270,.12,'sine',.018,.04)}
function playMeditationSound(){tone(220,.8,'sine',.045);tone(330,1,'sine',.035,.12);tone(495,1.2,'sine',.028,.28);tone(660,1.4,'sine',.018,.46)}
function showMeditationAnimation(gain=0,recovery=0){playMeditationSound();const backdrop=document.createElement('div');backdrop.className='meditation-backdrop';const toast=document.createElement('div');toast.className='meditation-toast';toast.setAttribute('role','status');toast.setAttribute('aria-live','polite');toast.innerHTML=`<strong>打坐完成</strong><span>灵台清明 · 灵力 +${gain} · 气血 +${recovery} · 寿元 -0.5</span>`;document.body.append(backdrop,toast);setTimeout(()=>{backdrop.remove();toast.remove()},1600)}
let musicTimer=null,musicPlaying=false,musicEnabled=true,musicVolume=1,musicBus=null;
function renderMusicButton(){const button=$('musicToggle');if(!button)return;button.classList.toggle('is-on',musicPlaying);button.setAttribute('aria-pressed',String(musicPlaying));button.textContent=musicPlaying?'♫ 音乐中':musicEnabled?'♫ 音乐':'♫ 音乐已关'}
function loadMusicSettings(){try{const currentRaw=localStorage.getItem(MUSIC_VOLUME_KEY),legacyRaw=currentRaw===null?localStorage.getItem(LEGACY_MUSIC_VOLUME_KEY):null,savedVolume=Number(currentRaw??legacyRaw);if(Number.isFinite(savedVolume)&&savedVolume>=0&&savedVolume<=1&&(currentRaw!==null||savedVolume>0))musicVolume=savedVolume;const savedEnabled=localStorage.getItem(MUSIC_ENABLED_KEY);if(savedEnabled==='0')musicEnabled=false}catch(error){}const input=$('musicVolume'),percent=Math.round(musicVolume*100);if(input){input.value=String(percent);input.setAttribute('aria-valuetext',`${percent}%`)}const output=$('musicVolumeValue');if(output)output.textContent=`${percent}%`;renderMusicButton()}
loadMusicSettings();
