const renderLegacyPanelWithCausalBoon=renderLegacyPanel;renderLegacyPanel=function(){renderLegacyPanelWithCausalBoon();const choices=$('legacyChoices');if(!choices||choices.querySelector('[data-boon="causal"]')){const selected=choices?.querySelector('[data-boon="causal"]');if(selected)selected.classList.toggle('selected',meta?.selectedBoon==='causal');return}const unlocked=legacyBoonUnlocked('causal'),button=document.createElement('button');button.dataset.boon='causal';button.className=unlocked?'legacy-causal-boon':'legacy-causal-boon legacy-locked';button.disabled=!unlocked;button.innerHTML=`<b>${unlocked?'因果罗盘':'未解锁传承'}</b><span>${unlocked?legacyBoons.causal.desc:'收集 5 种不同结局后解锁'}</span>`;choices.append(button);if(unlocked)button.onclick=()=>selectLegacyBoon('causal')};
