function lifeCostPreview(){if(!state||state.scene==='prologue')return'';const cost=choiceLifeCost(),remaining=Math.max(0,Number(state.life)-cost);return Number(state.life)<cost?'寿元不足半年 · 本轮无法行动':`寿元 -${cost}（预计余寿 ${formatYears(remaining)} 年）`}
