const setDragPreviewWithLifeForecast=setDragPreview;setDragPreview=function(direction){setDragPreviewWithLifeForecast(direction);const preview=ensureDragPreview();if(preview&&!preview.classList.contains('blocked')&&lifeCostPreview())preview.textContent=preview.textContent.replace(`寿元 -${choiceLifeCost()}`,lifeCostPreview())};
