function ensureChoiceRiskStyles(){if($('choiceRiskStyles'))return;const style=document.createElement('style');style.id='choiceRiskStyles';style.textContent='.side-choice.choice-risk{border-color:#bd6952;background:#f5ddd4;box-shadow:0 0 0 3px #bd695226}.side-choice.choice-risk>span{color:#aa4e3b}.side-choice.choice-risk em{color:#9d4f3e;font-weight:700}.side-choice.choice-risk:hover{background:#b85d43}.side-choice.choice-risk:focus-visible{outline:2px solid #9b4a36;outline-offset:3px}';document.head.append(style)}
