function renderDecisionCostBadge(){const chapterNode=document.querySelector('.chapter'),event=currentEvent();if(!chapterNode||!event||!state)return;ensureDecisionCostStyles();let badge=$('decisionCostBadge');if(!badge){badge=document.createElement('div');badge.id='decisionCostBadge';badge.className='decision-cost-badge';badge.setAttribute('role','status');badge.setAttribute('aria-live','polite');chapterNode.after(badge)}if(state.scene==='prologue'){badge.textContent='入门试炼 · 本阶段不消耗寿元';badge.className='decision-cost-badge prologue'}else{const meditationBlocked=Boolean(event.lockedUp);badge.textContent=meditationBlocked?'本轮行动 · 左右抉择 -0.5 年 · 打坐受阻':'本轮行动 · 左右抉择 -0.5 年 · ↑ 打坐 -0.5 年';badge.className=`decision-cost-badge${meditationBlocked?' blocked':''}`}badge.title=state.scene==='prologue'?'完成山门试炼后，正式修行才开始计时。':`每次行动推进半年；当前余寿 ${formatYears(state.life)} 年。`}
